@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var css = stepIndex == CurrentStep ? "step active"
                : stepIndex < CurrentStep ? "step completed"
                : "step future";

        <div class="@css" @onclick="() => OnStepClick(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>

        @if (stepIndex < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Email" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea @bind="Address" @bind:event="oninput" class="form-control"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @(isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Data { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";
    private string? errorMessage;
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            FullName = Data.FullName;
            Email = Data.Email;
            Phone = Data.Phone;
            Address = Data.Address;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            errorMessage = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email.Trim());
            if (!emailValid)
            {
                errorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
        }
        finally
        {
            isValidating = false;
        }
    }
}

@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(company: e.Value?.ToString())" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(title: e.Value?.ToString())" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="HandleStartDateChange" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="HandleEndDateChange"
                   class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(description: e.Value?.ToString())" class="form-control"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void Update(string? company = null, string? title = null, DateTime? startDate = null,
                        DateTime? endDate = null, bool? clearEndDate = null, string? description = null)
    {
        var updated = new WorkEntry(
            company ?? Entry.Company,
            title ?? Entry.Title,
            startDate ?? Entry.StartDate,
            clearEndDate == true ? null : (endDate ?? Entry.EndDate),
            description ?? Entry.Description
        );
        OnChanged.InvokeAsync(updated);
    }

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Update(startDate: date);
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Update(endDate: date);
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        if (isCurrent)
            Update(clearEndDate: true);
        else
            Update(endDate: DateTime.Today);
    }

    private async Task HandleRemove() => await OnRemove.InvokeAsync();
}

@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="entries[index]" Index="index"
                       CanRemove="entries.Count > 1"
                       OnChanged="e => HandleEntryChanged(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Data { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Entries.Count > 0)
        {
            entries = Data.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
            entries.RemoveAt(index);
    }

    private void HandleEntryChanged(int index, WorkEntry updated)
    {
        entries[index] = updated;
    }

    private async Task HandleNext()
    {
        errorMessage = null;
        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Company name and job title are required for each position.";
                return;
            }
        }
        await OnNext.InvokeAsync(new WorkHistory(entries.ToList()));
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}

