<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(company: e.Value?.ToString())" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(title: e.Value?.ToString())" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="HandleStartDateChange" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="HandleEndDateChange"
                   class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(description: e.Value?.ToString())" class="form-control"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void Update(string? company = null, string? title = null, DateTime? startDate = null,
                        DateTime? endDate = null, bool? clearEndDate = null, string? description = null)
    {
        var updated = new WorkEntry(
            company ?? Entry.Company,
            title ?? Entry.Title,
            startDate ?? Entry.StartDate,
            clearEndDate == true ? null : (endDate ?? Entry.EndDate),
            description ?? Entry.Description
        );
        OnChanged.InvokeAsync(updated);
    }

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Update(startDate: date);
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
            Update(endDate: date);
    }

    private void HandleCurrentChange(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        if (isCurrent)
            Update(clearEndDate: true);
        else
            Update(endDate: DateTime.Today);
    }

    private async Task HandleRemove() => await OnRemove.InvokeAsync();
}
