    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="entries[index]" Index="index"
                       CanRemove="entries.Count > 1"
                       OnChanged="e => HandleEntryChanged(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? Data { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Entries.Count > 0)
        {
            entries = Data.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
            entries.RemoveAt(index);
    }

    private void HandleEntryChanged(int index, WorkEntry updated)
    {
        entries[index] = updated;
    }

    private async Task HandleNext()
    {
        errorMessage = null;
        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Company name and job title are required for each position.";
                return;
            }
        }
        await OnNext.InvokeAsync(new WorkHistory(entries.ToList()));
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}
