@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="references-step">
    <h3>References</h3>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <ReferenceForm Ref="references[index]" Index="index"
                       CanRemove="references.Count > 2"
                       OnChanged="e => HandleRefChanged(index, e)"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (references.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? Data { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            references = Data.ToList();
        }
        else if (references.Count == 0)
        {
            references.Add(new Reference("", "", "", ""));
            references.Add(new Reference("", "", "", ""));
        }
    }

    private void AddRef()
    {
        if (references.Count < 3)
            references.Add(new Reference("", "", "", ""));
    }

    private void RemoveRef(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void HandleRefChanged(int index, Reference updated)
    {
        references[index] = updated;
    }

    private async Task HandleNext()
