@namespace sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply

<div class="cover-letter-step">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <textarea @bind="coverLetter" @bind:event="oninput" class="form-control cover-letter-textarea"
                  maxlength="2000" placeholder="Write your cover letter here..."></textarea>
        <div class="char-count">@coverLetter.Length / 2000 characters</div>
    </div>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-message">@errorMessage</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string? Data { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string coverLetter = "";
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (!string.IsNullOrEmpty(Data))
            coverLetter = Data;
    }

    private async Task HandleNext()
    {
        errorMessage = null;
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            errorMessage = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(coverLetter);
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();
}

