@page "/apply"
@rendermode InteractiveServer
@using sv_5121c8938b9e4b2e94b9daeb27d1f10d.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Data="personalInfo" OnNext="HandlePersonalNext" ApplicationService="ApplicationService" />
                break;
            case 1:
                <WorkHistoryStep Data="workHistory" OnNext="HandleWorkNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep Data="references" OnNext="HandleRefsNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep Data="coverLetter" OnNext="HandleCoverNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="personalInfo" Work="workHistory" References="references"
                           CoverLetter="coverLetter" ApplicationService="ApplicationService"
                           OnEditSection="GoToStep" OnBack="GoBack" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private PersonalInfo? personalInfo;
    private WorkHistory? workHistory;
    private List<Reference>? references;
    private string? coverLetter;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalNext(PersonalInfo data)
    {
        personalInfo = data;
        currentStep = 1;
    }

    private void HandleWorkNext(WorkHistory data)
    {
        workHistory = data;
        currentStep = 2;
    }

    private void HandleRefsNext(List<Reference> data)
    {
        references = data;
        currentStep = 3;
    }

    private void HandleCoverNext(string data)
    {
        coverLetter = data;
        currentStep = 4;
    }
}

